import React, { FormEvent, useEffect, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { QueryClient, QueryClientProvider, useQuery, useQueryClient } from '@tanstack/react-query';
import './styles.css';
import './calendar.css';
const api = import.meta.env.VITE_API_URL ?? 'http://localhost:3000/api';
type Session = { accessToken: string; user: { name: string; tenantId: string } };
type View = 'Resumen' | 'Agenda' | 'Pacientes' | 'Profesionales' | 'Servicios' | 'Tratamientos' | 'Seguimiento' | 'Horarios';
type Terminology = { customer: string; customers: string; professional: string; professionals: string; appointment: string; appointments: string; service: string; services: string };
const clinicTerminology: Terminology = { customer: 'paciente', customers: 'pacientes', professional: 'profesional', professionals: 'profesionales', appointment: 'cita', appointments: 'citas', service: 'servicio', services: 'servicios' };
function request(path: string, token: string, body?: unknown, method?: 'PATCH') { return fetch(`${api}${path}`, { method: method ?? (body ? 'POST' : 'GET'), headers: { Authorization: `Bearer ${token}`, ...(body ? { 'Content-Type': 'application/json' } : {}) }, body: body ? JSON.stringify(body) : undefined }).then(async r => { const data = await r.json(); if (r.status === 401) window.dispatchEvent(new Event('nexoclinic:session-expired')); if (!r.ok) throw new Error(Array.isArray(data.message) ? data.message.join(', ') : data.message ?? 'Error'); return data; }); }
function Directory({ session, view }: { session: Session; view: Exclude<View, 'Resumen' | 'Horarios'> }) {
  const query = useQuery({ queryKey: [view], queryFn: () => request(view === 'Pacientes' ? '/patients' : view === 'Profesionales' ? '/professionals' : '/services', session.accessToken) });
  const qc = useQueryClient(); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [editingId, setEditingId] = useState(''); const [editDraft, setEditDraft] = useState<Record<string,string>>({}); const [editError, setEditError] = useState('');
  const fields = view === 'Pacientes' ? [['firstName','Nombre'],['lastName','Apellidos'],['email','Correo'],['phone','Teléfono']] : view === 'Profesionales' ? [['firstName','Nombre'],['lastName','Apellidos'],['specialty','Especialidad'],['email','Correo'],['phone','Teléfono']] : [['name','Nombre'],['description','Descripción'],['durationMinutes','Duración (minutos)'],['priceEuros','Precio (€)']];
  const basePath = view === 'Pacientes' ? '/patients' : view === 'Profesionales' ? '/professionals' : '/services';
  function itemName(item: any) { return item.firstName ? `${item.firstName} ${item.lastName}` : item.name; }
  function beginEdit(item: any) { setEditError(''); setEditingId(item.id); setEditDraft(Object.fromEntries(fields.map(([key]) => [key, item[key] == null ? '' : String(item[key])] ))); }
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const form = e.currentTarget; const raw = Object.fromEntries(new FormData(form)); const body = view === 'Servicios' ? { name: raw.name, description: raw.description || undefined, durationMinutes: Number(raw.durationMinutes), priceEuros: raw.priceEuros === '' ? undefined : Number(raw.priceEuros) } : { ...raw, email: raw.email || undefined, phone: raw.phone || undefined }; setError(''); try { await request(basePath, session.accessToken, body); form.reset(); await qc.invalidateQueries({ queryKey: [view] }); await qc.invalidateQueries({ queryKey: ['services-agenda'] }); await qc.invalidateQueries({ queryKey: ['treatment-default-durations'] }); setMessage(`${view.slice(0,-1)} guardado correctamente.`); } catch (e) { setError(e instanceof Error ? e.message : 'No se pudo guardar'); } }
  async function saveEdit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); setEditError(''); const body: Record<string,unknown> = { ...editDraft }; if (view === 'Servicios') { body.durationMinutes = Number(editDraft.durationMinutes); body.priceEuros = editDraft.priceEuros === '' ? null : Number(editDraft.priceEuros); body.description = editDraft.description || null; } else { if (!editDraft.email) body.email = null; if (!editDraft.phone) body.phone = null; } try { await request(`${basePath}/${editingId}`, session.accessToken, body, 'PATCH'); setEditingId(''); setMessage(`${view.slice(0,-1)} actualizado correctamente.`); await Promise.all([qc.invalidateQueries({ queryKey: [view] }),qc.invalidateQueries({ queryKey: ['professionals-agenda'] }),qc.invalidateQueries({ queryKey: ['schedule-professionals'] }),qc.invalidateQueries({ queryKey: ['services-agenda'] }),qc.invalidateQueries({ queryKey: ['treatment-default-durations'] }),qc.invalidateQueries({ queryKey: ['patients-agenda'] }),qc.invalidateQueries({ queryKey: ['patients-follow-ups'] })]); } catch (e) { setEditError(e instanceof Error ? e.message : 'No se pudo editar'); } }
  function renderField(name: string, label: string, value?: string, onChange?: (v:string)=>void) { return <label key={name}>{label}{name === 'durationMinutes' ? <select name={value === undefined ? name : undefined} required value={value ?? '30'} onChange={e=>onChange?.(e.target.value)}><option value="15">15 minutos</option><option value="30">30 minutos</option><option value="60">1 hora</option></select> : name === 'description' ? <textarea name={value === undefined ? name : undefined} value={value} onChange={e=>onChange?.(e.target.value)} rows={2}/> : <input value={value} onChange={e=>onChange?.(e.target.value)} name={value === undefined ? name : undefined} type={name === 'email' ? 'email' : name === 'priceEuros' ? 'number' : 'text'} required={name !== 'email' && name !== 'phone' && name !== 'priceEuros' && name !== 'description'} min={name === 'priceEuros' ? 0 : undefined} step={name === 'priceEuros' ? '0.01' : undefined} />}</label>; }
  return <><header><div><p className="eyebrow">Gestión de clínica</p><h1>{view}</h1><p>Administra y actualiza la información de tu clínica.</p></div></header><section className="management directory-layout"><form className="directory-create" onSubmit={submit}><h2>Añadir {view === 'Pacientes' ? 'paciente' : view === 'Profesionales' ? 'profesional' : 'servicio'}</h2>{fields.map(([name,label])=>renderField(name,label))}{error&&<p className="error">{error}</p>}{message&&<p className="success">{message}</p>}<button className="primary">Guardar</button></form><section className="panel directory-list-panel"><div className="directory-list-heading"><div><p className="eyebrow">Gestión</p><h2>Listado de {view.toLowerCase()}</h2></div><span className="schedule-total">{query.data?.length??0}</span></div>{query.isLoading?<p>Cargando…</p>:query.isError?<p className="error">No se pudieron cargar los datos.</p>:query.data.length===0?<p className="empty">Todavía no hay registros.</p>:<ul className="directory-list">{query.data.map((item:any)=><li className="directory-record" key={item.id}><div className="directory-record-summary"><b>{itemName(item)}</b><span>{view==='Profesionales'?`${item.specialty}${item.email?' · '+item.email:''}${item.phone?' · '+item.phone:''}`:view==='Pacientes'?`${item.email??'Sin correo'}${item.phone?' · '+item.phone:''}`:`${item.durationMinutes} min · ${new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(Number(item.priceEuros??0))}${item.description?' · '+item.description:''}`}</span></div><button type="button" className="secondary directory-edit-button" onClick={()=>editingId===item.id?setEditingId(''):beginEdit(item)}>Editar</button>{editingId===item.id&&<form className="directory-edit-form" onSubmit={saveEdit}>{fields.map(([name,label])=>renderField(name,label,editDraft[name],value=>setEditDraft(current=>({...current,[name]:value}))) )}{editError&&<p className="error">{editError}</p>}<div className="directory-edit-actions"><button className="primary">Guardar cambios</button><button type="button" className="secondary" onClick={()=>setEditingId('')}>Cancelar</button></div></form>}</li>)}</ul>}</section></section></>;
}
function Agenda({ session }: { session: Session }) {
  const qc = useQueryClient(); const [error, setError] = useState(''); const [professionalId, setProfessionalId] = useState(''); const [serviceId, setServiceId] = useState(''); const [startsAtInput, setStartsAtInput] = useState(''); const [editingId, setEditingId] = useState(''); const [editDraft, setEditDraft] = useState({ patientId: '', professionalId: '', serviceId: '', startsAt: '' }); const [editError, setEditError] = useState('');
  const patients = useQuery({ queryKey: ['patients-agenda'], queryFn: () => request('/patients', session.accessToken) });
  const professionals = useQuery({ queryKey: ['professionals-agenda'], queryFn: () => request('/professionals', session.accessToken) });
  const services = useQuery({ queryKey: ['services-agenda'], queryFn: () => request('/services', session.accessToken) });
  const appointments = useQuery({ queryKey: ['appointments'], queryFn: () => request('/appointments', session.accessToken) });
  const selectedService = services.data?.find((item: any) => item.id === serviceId); const duration = Number(selectedService?.durationMinutes ?? 30);
  const availability = useQuery({ queryKey: ['appointment-availability', professionalId, serviceId], queryFn: () => request(`/appointments/availability?professionalId=${encodeURIComponent(professionalId)}&serviceId=${encodeURIComponent(serviceId)}`, session.accessToken), enabled: Boolean(professionalId && serviceId) });
  function suggestedDateTime(iso: string) { const date = new Date(iso); const local = new Date(date.getTime() - date.getTimezoneOffset() * 60000); return local.toISOString().slice(0, 16); }
  function startEditing(appointment: any) { setEditError(''); setEditingId(appointment.id); setEditDraft({ patientId: appointment.patientId, professionalId: appointment.professionalId, serviceId: appointment.serviceId ?? '', startsAt: suggestedDateTime(appointment.startsAt) }); }
  async function saveEdit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const service = services.data?.find((item: any) => item.id === editDraft.serviceId); if (!service) { setEditError('Selecciona un tratamiento válido.'); return; } const startsAt = new Date(editDraft.startsAt).toISOString(); const endsAt = new Date(new Date(startsAt).getTime() + Number(service.durationMinutes) * 60000).toISOString(); setEditError(''); try { await request(`/appointments/${editingId}/reschedule`, session.accessToken, { ...editDraft, startsAt, endsAt }, 'PATCH'); setEditingId(''); await Promise.all([qc.invalidateQueries({ queryKey: ['appointments'] }), qc.invalidateQueries({ queryKey: ['summary'] }), qc.invalidateQueries({ queryKey: ['calendar'] }), qc.invalidateQueries({ queryKey: ['appointment-availability'] })]); } catch (e) { setEditError(e instanceof Error ? e.message : 'No se pudo editar la cita'); } }
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const values = Object.fromEntries(new FormData(e.currentTarget)); setError(''); const startsAt = new Date(startsAtInput).toISOString(); const endsAt = new Date(new Date(startsAt).getTime() + duration * 60000).toISOString(); try { await request('/appointments', session.accessToken, { patientId: values.patientId, professionalId, serviceId, startsAt, endsAt }); setStartsAtInput(''); qc.invalidateQueries({ queryKey: ['appointments'] }); qc.invalidateQueries({ queryKey: ['summary'] }); qc.invalidateQueries({ queryKey: ['appointment-availability', professionalId, serviceId] }); qc.invalidateQueries({ queryKey: ['calendar'] }); } catch (e) { setError(e instanceof Error ? e.message : 'No se pudo reservar'); } }
  const firstSlot = availability.data?.firstAvailable;
  return <><header><div><p className="eyebrow">Agenda</p><h1>Reservas</h1><p>Elige tratamiento y profesional para encontrar un hueco que cubra la duración requerida.</p></div></header><section className="management appointments-page"><form onSubmit={submit}><h2>Nueva cita</h2><label>Paciente<select name="patientId" required defaultValue=""><option value="" disabled>Selecciona un paciente</option>{patients.data?.map((x:any)=><option value={x.id} key={x.id}>{x.firstName} {x.lastName}</option>)}</select></label><label>Tratamiento<select value={serviceId} onChange={e => { setServiceId(e.target.value); setStartsAtInput(''); }} required><option value="">Selecciona un tratamiento</option>{services.data?.filter((x:any) => x.active).map((x:any)=><option value={x.id} key={x.id}>{x.name} · {x.durationMinutes} min</option>)}</select></label>{selectedService && <p className="schedule-period">Duración predeterminada: {duration} minutos{selectedService.priceEuros != null ? ` · ${new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(Number(selectedService.priceEuros))}` : ''}</p>}<label>Profesional<select value={professionalId} onChange={e => { setProfessionalId(e.target.value); setStartsAtInput(''); }} required><option value="">Selecciona un profesional</option>{professionals.data?.map((x:any)=><option value={x.id} key={x.id}>{x.firstName} {x.lastName} · {x.specialty}</option>)}</select></label>{professionalId && serviceId && <div className="availability-suggestion">{availability.isLoading ? <p>Buscando huecos disponibles…</p> : availability.isError ? <p className="error">No se pudo consultar la disponibilidad del profesional.</p> : firstSlot ? <><b>Primera cita disponible</b><p>{firstSlot.localStart}–{firstSlot.localEnd} · {availability.data.timezone}</p><button type="button" className="secondary" onClick={() => setStartsAtInput(suggestedDateTime(firstSlot.startsAt))}>Usar este horario</button>{availability.data.slots.length > 1 && <details><summary>Ver otros huecos próximos</summary><ul className="suggested-slots">{availability.data.slots.slice(1).map((slot:any)=><li key={slot.startsAt}><button type="button" className="link" onClick={() => setStartsAtInput(suggestedDateTime(slot.startsAt))}>{slot.localStart}–{slot.localEnd}</button></li>)}</ul></details>}</> : <p className="empty">No hay huecos para este profesional en los próximos 45 días. Revisa sus horarios o elige otro profesional.</p>}</div>}<label>Fecha y hora<input name="startsAt" type="datetime-local" required value={startsAtInput} onChange={e => setStartsAtInput(e.target.value)} /></label>{startsAtInput && <p className="schedule-period">La hora seleccionada se comprobará de nuevo al reservar, por si otro usuario ocupó el hueco.</p>}{error&&<p className="error">{error}</p>}<button className="primary" disabled={!patients.data?.length||!professionalId||!serviceId||availability.isLoading}>Reservar cita</button></form><section className="panel appointment-list-panel"><h2>Próximas citas</h2>{appointments.isLoading?<p>Cargando…</p>:appointments.data?.length?<ul className="appointment-list">{appointments.data.map((x:any)=><li className="appointment-card" key={x.id}><div className="appointment-summary"><b>{x.patient.firstName} {x.patient.lastName}</b><span>{x.professional.firstName} {x.professional.lastName} · {x.service?.name ?? 'Tratamiento'} · {new Date(x.startsAt).toLocaleString('es-ES')}</span><span>{new Date(x.startsAt).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}–{new Date(x.endsAt).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}</span></div><button type="button" className="secondary appointment-edit-toggle" onClick={() => editingId === x.id ? setEditingId('') : startEditing(x)}>Editar cita</button>{editingId === x.id && <form className="appointment-edit-form" onSubmit={saveEdit}><label>Paciente<select required value={editDraft.patientId} onChange={e => setEditDraft({...editDraft, patientId:e.target.value})}>{patients.data?.map((p:any)=><option value={p.id} key={p.id}>{p.firstName} {p.lastName}</option>)}</select></label><label>Profesional<select required value={editDraft.professionalId} onChange={e => setEditDraft({...editDraft, professionalId:e.target.value})}>{professionals.data?.map((p:any)=><option value={p.id} key={p.id}>{p.firstName} {p.lastName}</option>)}</select></label><label>Tratamiento<select required value={editDraft.serviceId} onChange={e => setEditDraft({...editDraft, serviceId:e.target.value})}>{services.data?.filter((s:any)=>s.active).map((s:any)=><option value={s.id} key={s.id}>{s.name} · {s.durationMinutes} min</option>)}</select></label><label>Fecha y hora<input type="datetime-local" required value={editDraft.startsAt} onChange={e => setEditDraft({...editDraft, startsAt:e.target.value})}/></label>{editError && <p className="error">{editError}</p>}<div className="appointment-edit-actions"><button className="primary">Guardar cambios</button><button type="button" className="secondary" onClick={() => setEditingId('')}>Cancelar</button></div></form>}</li>)}</ul>:<p className="empty">Añade pacientes, tratamientos y profesionales para reservar la primera cita.</p>}</section></section></>;
}
function TreatmentDurations({ session }: { session: Session }) {
  const services = useQuery({ queryKey: ['treatment-default-durations'], queryFn: () => request('/services', session.accessToken) }); const qc = useQueryClient(); const [durations, setDurations] = useState<Record<string,string>>({}); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const [editingServiceId, setEditingServiceId] = useState(''); const [serviceDraft, setServiceDraft] = useState({ name: '', description: '', priceEuros: '' }); const [editError, setEditError] = useState('');
  function startServiceEdit(service: any) { setEditError(''); setEditingServiceId(service.id); setServiceDraft({ name: service.name, description: service.description ?? '', priceEuros: service.priceEuros == null ? '' : String(Number(service.priceEuros)) }); }
  async function saveServiceEdit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); setEditError(''); try { await request(`/services/${editingServiceId}`, session.accessToken, { name: serviceDraft.name.trim(), description: serviceDraft.description.trim() || null, priceEuros: serviceDraft.priceEuros === '' ? null : Number(serviceDraft.priceEuros) }, 'PATCH'); await Promise.all([qc.invalidateQueries({ queryKey: ['Servicios'] }), qc.invalidateQueries({ queryKey: ['services-agenda'] }), qc.invalidateQueries({ queryKey: ['treatment-default-durations'] })]); setEditingServiceId(''); setMessage('Tratamiento actualizado.'); } catch (e) { setEditError(e instanceof Error ? e.message : 'No se pudo editar el tratamiento'); } }
  async function save(id: string) { setError(''); setMessage(''); const durationMinutes = Number(durations[id]); if (![15,30,60].includes(durationMinutes)) { setError('Elige 15, 30 o 60 minutos.'); return; } try { await request(`/services/${id}/duration`, session.accessToken, { durationMinutes }, 'PATCH'); await Promise.all([qc.invalidateQueries({ queryKey: ['Servicios'] }), qc.invalidateQueries({ queryKey: ['services-agenda'] }), qc.invalidateQueries({ queryKey: ['appointment-availability'] }), qc.invalidateQueries({ queryKey: ['treatment-default-durations'] })]); setMessage('Duración predeterminada actualizada.'); } catch (e) { setError(e instanceof Error ? e.message : 'No se pudo guardar la duración'); } }
  return <><header><div><p className="eyebrow">Configuración de tratamientos</p><h1>Duración predeterminada</h1><p>Elige 15, 30 o 60 minutos. La agenda encajará cada cita según el tratamiento.</p></div></header><section className="treatment-duration-page"><div className="treatment-intro"><span aria-hidden="true">◷</span><div><b>Duración para cada tratamiento</b><p>El asistente de disponibilidad propondrá huecos de 15 minutos y respetará la duración seleccionada.</p></div></div>{message && <p className="success">{message}</p>}{error && <p className="error">{error}</p>}{services.isLoading ? <p>Cargando tratamientos…</p> : services.isError ? <p className="error">No se pudieron cargar los tratamientos.</p> : services.data?.length ? <div className="treatment-duration-list">{services.data.filter((service:any) => service.active).map((service:any) => {const current=Number(durations[service.id] ?? service.durationMinutes);const allowed=[15,30,60].includes(current);return <div className="treatment-duration-card" key={service.id}><div className="treatment-name"><b>{service.name}</b><span>{service.priceEuros != null ? new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(Number(service.priceEuros)) : 'Precio no indicado'}</span>{service.description && <small>{service.description}</small>}</div><label>Duración<select value={durations[service.id] ?? String(service.durationMinutes)} onChange={e => setDurations(current => ({ ...current, [service.id]: e.target.value }))}>{![15,30,60].includes(Number(service.durationMinutes))&&<option value={String(service.durationMinutes)}>{service.durationMinutes} min · actual</option>}<option value="15">15 minutos</option><option value="30">30 minutos</option><option value="60">1 hora</option></select></label><div className="treatment-card-actions"><button type="button" className="secondary" disabled={!allowed} onClick={() => void save(service.id)}>Guardar duración</button><button type="button" className="secondary treatment-edit-toggle" onClick={() => editingServiceId === service.id ? setEditingServiceId('') : startServiceEdit(service)}>Editar tratamiento</button></div>{editingServiceId === service.id && <form className="treatment-edit-form" onSubmit={saveServiceEdit}><label>Nombre<input required minLength={2} value={serviceDraft.name} onChange={e => setServiceDraft({...serviceDraft,name:e.target.value})}/></label><label>Descripción<input value={serviceDraft.description} onChange={e => setServiceDraft({...serviceDraft,description:e.target.value})}/></label><label>Precio (€)<input type="number" min="0" step="0.01" value={serviceDraft.priceEuros} onChange={e => setServiceDraft({...serviceDraft,priceEuros:e.target.value})}/></label>{editError && <p className="error">{editError}</p>}<div className="treatment-edit-actions"><button className="primary">Guardar cambios</button><button type="button" className="secondary" onClick={() => setEditingServiceId('')}>Cancelar</button></div></form>}</div>})}</div> : <p className="empty">Crea primero los tratamientos desde la sección Servicios.</p>}</section></>;
}
function FollowUps({ session }: { session: Session }) {
  const qc = useQueryClient(); const [error, setError] = useState(''); const [editingId,setEditingId]=useState(''); const [editError,setEditError]=useState(''); const [draft,setDraft]=useState({patientId:'',title:'',notes:'',dueAt:''});
  const patients = useQuery({ queryKey: ['patients-follow-ups'], queryFn: () => request('/patients', session.accessToken) });
  const followUps = useQuery({ queryKey: ['follow-ups'], queryFn: () => request('/follow-ups', session.accessToken) });
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const form = e.currentTarget; const values = Object.fromEntries(new FormData(form)); try { await request('/follow-ups', session.accessToken, { patientId: values.patientId, title: values.title, notes: values.notes || undefined, dueAt: values.dueAt ? new Date(String(values.dueAt)).toISOString() : undefined }); form.reset(); qc.invalidateQueries({ queryKey: ['follow-ups'] }); } catch (e) { setError(e instanceof Error ? e.message : 'No se pudo crear el seguimiento'); } }
  async function complete(id: string) { try { await request('/follow-ups/' + id + '/status', session.accessToken, { status: 'COMPLETED' }, 'PATCH'); qc.invalidateQueries({ queryKey: ['follow-ups'] }); } catch (e) { setError(e instanceof Error ? e.message : 'No se pudo actualizar el seguimiento'); } }
  function beginEdit(x:any){const d=x.dueAt?new Date(x.dueAt):null;setDraft({patientId:x.patientId,title:x.title,notes:x.notes??'',dueAt:d?new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16):''});setEditingId(x.id);setEditError('')}
  async function saveEdit(e:FormEvent<HTMLFormElement>){e.preventDefault();setEditError('');try{await request('/follow-ups/'+editingId,session.accessToken,{...draft,dueAt:draft.dueAt?new Date(draft.dueAt).toISOString():null,notes:draft.notes||null},'PATCH');setEditingId('');await qc.invalidateQueries({queryKey:['follow-ups']})}catch(e){setEditError(e instanceof Error?e.message:'No se pudo editar el seguimiento')}}
  return <><header><div><p className="eyebrow">Atención al paciente</p><h1>Seguimiento</h1><p>Organiza las llamadas y tareas posteriores a cada atención.</p></div></header><section className="management directory-layout"><form className="directory-create" onSubmit={submit}><h2>Nueva tarea</h2><label>Paciente<select name="patientId" required><option value="">Selecciona un paciente</option>{patients.data?.map((x:any)=><option value={x.id} key={x.id}>{x.firstName} {x.lastName}</option>)}</select></label><label>Asunto<input name="title" required minLength={2} /></label><label>Fecha límite<input name="dueAt" type="datetime-local" /></label><label>Notas<textarea name="notes" rows={3} /></label>{error&&<p className="error">{error}</p>}<button className="primary" disabled={!patients.data?.length}>Guardar seguimiento</button></form><section className="panel directory-list-panel"><div className="directory-list-heading"><div><p className="eyebrow">Atención</p><h2>Tareas de seguimiento</h2></div><span className="schedule-total">{followUps.data?.length??0}</span></div>{followUps.isLoading?<p>Cargando…</p>:followUps.data?.length?<ul className="directory-list">{followUps.data.map((x:any)=><li key={x.id} className="directory-record"><div className="directory-record-summary"><b>{x.title}</b><span>{x.patient.firstName} {x.patient.lastName}{x.dueAt?' · '+new Date(x.dueAt).toLocaleString('es-ES'):''}</span><span className={'status status-'+(x.status==='PENDING'?'pending':'completed')}>{x.status==='PENDING'?'Pendiente':'Completado'}</span></div><div className="directory-record-actions"><button type="button" className="secondary directory-edit-button" onClick={()=>editingId===x.id?setEditingId(''):beginEdit(x)}>Editar</button>{x.status==='PENDING'&&<button type="button" className="secondary" onClick={()=>complete(x.id)}>Completar</button>}</div>{editingId===x.id&&<form className="directory-edit-form" onSubmit={saveEdit}><label>Paciente<select required value={draft.patientId} onChange={e=>setDraft({...draft,patientId:e.target.value})}>{patients.data?.map((p:any)=><option key={p.id} value={p.id}>{p.firstName} {p.lastName}</option>)}</select></label><label>Asunto<input required minLength={2} value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})}/></label><label>Fecha límite<input type="datetime-local" value={draft.dueAt} onChange={e=>setDraft({...draft,dueAt:e.target.value})}/></label><label>Notas<textarea rows={3} value={draft.notes} onChange={e=>setDraft({...draft,notes:e.target.value})}/></label>{editError&&<p className="error">{editError}</p>}<div className="directory-edit-actions"><button className="primary">Guardar cambios</button><button type="button" className="secondary" onClick={()=>setEditingId('')}>Cancelar</button></div></form>}</li>)}</ul>:<p className="empty">No hay tareas de seguimiento.</p>}</section></section></>;
}
function ShiftReservation({ session, professionalId, weekday, startsAtMinute, validFrom, validTo }: { session: Session; professionalId: string; weekday: number; startsAtMinute: number; validFrom: string; validTo: string }) {
  const [open, setOpen] = useState(false); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [serviceId, setServiceId] = useState(''); const qc = useQueryClient();
  const patients = useQuery({ queryKey: ['shift-booking-patients'], queryFn: () => request('/patients', session.accessToken), enabled: open });
  const services = useQuery({ queryKey: ['shift-booking-services'], queryFn: () => request('/services', session.accessToken), enabled: open });
  const startTime = String(Math.floor(startsAtMinute / 60)).padStart(2,'0') + ':' + String(startsAtMinute % 60).padStart(2,'0');
  const dateOptions = { min: validFrom, max: validTo };
  function defaultDate() { const key = (date: Date) => date.getFullYear() + '-' + String(date.getMonth()+1).padStart(2,'0') + '-' + String(date.getDate()).padStart(2,'0'); const d = new Date(`${validFrom}T12:00:00`); while (key(d) <= validTo && d.getDay() !== weekday) d.setDate(d.getDate() + 1); const first = new Date(d); const today = new Date(); today.setHours(0,0,0,0); while (key(d) <= validTo && d < today) d.setDate(d.getDate() + 7); return key(d) <= validTo ? key(d) : key(first); }
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const values = Object.fromEntries(new FormData(e.currentTarget)); const service = services.data?.find((item:any) => item.id === serviceId); if (!service) { setError('Selecciona un tratamiento.'); return; } const startsAt = new Date(`${values.date}T${values.time}`).toISOString(); const endsAt = new Date(new Date(startsAt).getTime() + service.durationMinutes * 60000).toISOString(); setError(''); setMessage(''); try { await request('/appointments', session.accessToken, { patientId: values.patientId, professionalId, serviceId, startsAt, endsAt }); setMessage('Reserva añadida.'); setOpen(false); qc.invalidateQueries({ queryKey: ['appointments'] }); qc.invalidateQueries({ queryKey: ['summary'] }); qc.invalidateQueries({ queryKey: ['calendar'] }); qc.invalidateQueries({ queryKey: ['calendar-day'] }); } catch (e) { setError(e instanceof Error ? e.message : 'No se pudo guardar la reserva'); } }
  return <div className="shift-reservation"><button type="button" className="add-reservation" aria-expanded={open} onClick={() => { setOpen(!open); setError(''); setMessage(''); }}><span>＋</span> Añadir reserva manual</button>{message && <p className="success booking-success">{message}</p>}{open && <form className="shift-booking-form" onSubmit={submit}><label>Fecha<input name="date" type="date" required defaultValue={defaultDate()} {...dateOptions} /></label><label>Paciente<select name="patientId" required defaultValue=""><option value="" disabled>Selecciona paciente</option>{patients.data?.map((patient:any)=><option key={patient.id} value={patient.id}>{patient.firstName} {patient.lastName}</option>)}</select></label><label>Tratamiento<select value={serviceId} onChange={e => setServiceId(e.target.value)} required><option value="">Selecciona tratamiento</option>{services.data?.filter((service:any)=>service.active).map((service:any)=><option key={service.id} value={service.id}>{service.name} · {service.durationMinutes} min</option>)}</select></label><label>Inicio<input name="time" type="time" required defaultValue={startTime} /></label>{error && <p className="error">{error}</p>}<button className="primary" disabled={!patients.data?.length || !services.data?.length}>Confirmar reserva</button></form>}</div>;
}

function Schedules({ session }: { session: Session }) {
  const now = new Date(); const [professionalId,setProfessionalId]=useState(''); const [error,setError]=useState(''); const [message,setMessage]=useState(''); const [shift,setShift]=useState<'morning'|'afternoon'>('morning'); const [shiftStart,setShiftStart]=useState('09:00'); const [shiftEnd,setShiftEnd]=useState('13:00'); const [month,setMonth]=useState(now.getMonth()+1); const [year,setYear]=useState(now.getFullYear()); const [weekday,setWeekday]=useState('1'); const [editingRuleId,setEditingRuleId]=useState(''); const [assistantAnswer,setAssistantAnswer]=useState(''); const [assistantError,setAssistantError]=useState(''); const [assistantBusy,setAssistantBusy]=useState(false); const qc=useQueryClient();
  const professionals=useQuery({queryKey:['schedule-professionals'],queryFn:()=>request('/professionals',session.accessToken)});
  const rules=useQuery({queryKey:['schedule-rules',professionalId],queryFn:()=>request('/scheduling/professionals/'+professionalId+'/rules',session.accessToken),enabled:Boolean(professionalId)});
  const weekdays=['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado']; const months=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  function minute(value:FormDataEntryValue|string|null){const [h,m]=String(value??'').split(':').map(Number);return h*60+m} function time(value:number){return String(Math.floor(value/60)).padStart(2,'0')+':'+String(value%60).padStart(2,'0')}
  const quarter=Math.floor((month-1)/3)+1; const firstMonth=(quarter-1)*3; const validFrom=year+'-'+String(firstMonth+1).padStart(2,'0')+'-01'; const validTo=new Date(Date.UTC(year,firstMonth+3,0)).toISOString().slice(0,10);
  function beginRuleEdit(rule:any){setEditingRuleId(rule.id);setProfessionalId(rule.professionalId);setWeekday(String(rule.weekday));const d=String(rule.validFrom).slice(0,10).split('-').map(Number);setYear(d[0]);setMonth(d[1]);setShift(rule.startsAtMinute<840?'morning':'afternoon');setShiftStart(time(rule.startsAtMinute));setShiftEnd(time(rule.endsAtMinute));setError('');setMessage('')}
  async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const values=new FormData(e.currentTarget);setError('');setMessage('');const weekdayValue=Number(weekday);const startsAtMinute=minute(values.get('startsAt'));const endsAtMinute=minute(values.get('endsAt'));if(weekdayValue<1||weekdayValue>5||endsAtMinute-startsAtMinute<15||endsAtMinute-startsAtMinute>300){setError('El turno debe ser de lunes a viernes y durar al menos 15 minutos, con una extensión máxima de 1 hora.');return}if(rules.data?.some((rule:any)=>rule.id!==editingRuleId&&rule.weekday===weekdayValue&&startsAtMinute<rule.endsAtMinute&&endsAtMinute>rule.startsAtMinute&&String(rule.validFrom).slice(0,10)<=validTo&&String(rule.validTo).slice(0,10)>=validFrom)){setError('Este turno se solapa con otro para el mismo día y periodo.');return}const body={professionalId,weekday:weekdayValue,startsAtMinute,endsAtMinute,validFrom,validTo};try{await request(editingRuleId?'/scheduling/rules/'+editingRuleId:'/scheduling/rules',session.accessToken,body,editingRuleId?'PATCH':undefined);setEditingRuleId('');qc.invalidateQueries({queryKey:['schedule-rules',professionalId]});qc.invalidateQueries({queryKey:['calendar']});setMessage(editingRuleId?'Horario actualizado.':'Horario guardado.')}catch(e){setError(e instanceof Error?e.message:'No se pudo guardar el horario')}}
  async function askAssistant(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;const data=new FormData(form);const question=String(data.get('question')??'').trim();if(!question)return;setAssistantError('');setAssistantBusy(true);try{const result=await request('/assistant/ask',session.accessToken,{question});setAssistantAnswer(result.answer);form.reset()}catch(e){setAssistantError(e instanceof Error?e.message:'No se pudo consultar al asistente')}finally{setAssistantBusy(false)}}
  const selected=professionals.data?.find((x:any)=>x.id===professionalId);
  const groups=(rules.data??[]).reduce((out:Record<string,any[]>,rule:any)=>{const [y,m]=String(rule.validFrom).slice(0,10).split('-').map(Number);const k=y+'-T'+(Math.floor((m-1)/3)+1);(out[k]??=[]).push(rule);return out},{});
  const quarterNames=['','Primer trimestre · Enero–Marzo','Segundo trimestre · Abril–Junio','Tercer trimestre · Julio–Septiembre','Cuarto trimestre · Octubre–Diciembre'];
  return <><header><div><p className="eyebrow">Configuración de agenda</p><h1>Horarios por trimestre</h1><p>Organiza los turnos de cada profesional por año, mes y día.</p></div></header><section className="management schedules-layout">
    <form className="schedule-form" onSubmit={submit}><h2>Añadir turno</h2>
      <label>Profesional<select value={professionalId} onChange={e=>setProfessionalId(e.target.value)} required><option value="">Selecciona un profesional</option>{professionals.data?.map((x:any)=><option key={x.id} value={x.id}>{x.firstName} {x.lastName} · {x.specialty}</option>)}</select></label>
      <div className="schedule-date-row"><label>Año<input type="number" min="2020" max="2100" value={year} onChange={e=>setYear(Number(e.target.value))}/></label><label>Mes<select value={month} onChange={e=>setMonth(Number(e.target.value))}>{months.map((m,i)=><option key={m} value={i+1}>{m}</option>)}</select></label><label>Día de la semana<select name="weekday" value={weekday} onChange={e=>setWeekday(e.target.value)} required>{weekdays.map((d,i)=>i>0&&i<6?<option key={d} value={i}>{d}</option>:null)}</select></label></div>
      <p className="schedule-period">Vigencia del trimestre: {validFrom} – {validTo}</p>
      <div className="shift-choice"><button type="button" className={shift==='morning'?'selected':''} onClick={()=>{setShift('morning');setShiftStart('09:00');setShiftEnd('13:00')}}>Mañana · 09:00–13:00</button><button type="button" className={shift==='afternoon'?'selected':''} onClick={()=>{setShift('afternoon');setShiftStart('16:00');setShiftEnd('20:00')}}>Tarde · 16:00–20:00</button></div>
      <div className="shift-time-row"><label>Empieza a las<select name="startsAt" required value={shiftStart} onChange={e=>{const start=e.target.value;setShiftStart(start);if(minute(shiftEnd)<=minute(start))setShiftEnd(time(minute(start)+15))}}>{Array.from({length:5},(_,i)=>{const value=time((shift==='morning'?540:960)+i*60);return <option key={value} value={value}>{value}</option>})}</select></label><label>Termina a las<select name="endsAt" required value={shiftEnd} onChange={e=>setShiftEnd(e.target.value)}>{Array.from({length:((shift==='morning'?840:1260)-minute(shiftStart))/15},(_,i)=>{const end=minute(shiftStart)+15*(i+1);const regular=shift==='morning'?780:1200;return <option key={end} value={time(end)}>{time(end)}{end===regular?' · habitual':end>regular?` · +${end-regular} min`:''}</option>})}</select></label></div>
      <p className="schedule-period">El inicio se elige por hora. El fin puede ajustarse cada 15 minutos hasta las 14:00 por la mañana o las 21:00 por la tarde. Las citas usan la duración asignada al tratamiento (15, 30 o 60 min).</p>
      {error&&<p className="error">{error}</p>}{message&&<p className="success">{message}</p>}<button className="primary" disabled={!professionalId}>{editingRuleId?'Guardar cambios':'Guardar turno'}</button>{editingRuleId&&<button type="button" className="secondary" onClick={()=>setEditingRuleId('')}>Cancelar edición</button>}
    </form>
    <section className="panel schedule-list-panel"><div className="schedule-list-heading"><div><p className="eyebrow">Planificación</p><h2>{selected?'Turnos de '+selected.firstName+' '+selected.lastName:'Turnos asignados'}</h2></div>{professionalId&&!rules.isLoading&&!rules.isError&&<span className="schedule-total">{rules.data?.length??0} turnos</span>}</div>
      <div className="ai-assistant-banner"><span className="ai-mark">✦</span><div><b>Asistente IA de planificación</b><p>Consulta cómo organizar turnos y citas según los horarios y las duraciones configuradas.</p><small>El asistente no ve la agenda real, no confirma reservas ni contacta pacientes. Para reservar, usa + en el turno o la sección Agenda.</small>{assistantAnswer&&<div className="assistant-answer" role="status">{assistantAnswer}</div>}{assistantError&&<p className="error" role="alert">{assistantError}</p>}<form className="assistant-ask" onSubmit={askAssistant}><input name="question" maxLength={1000} minLength={2} placeholder="Pregunta sobre turnos y planificación…" required/><button className="secondary" disabled={assistantBusy}>{assistantBusy?'Consultando…':'Preguntar'}</button></form></div><span className="ai-status">{assistantBusy?'Conectando…':'OpenAI'}</span></div>
      {!professionalId?<div className="schedule-empty"><span>◷</span><b>Tu planificación, de un vistazo</b><p>Selecciona un profesional para ver mañana y tarde en paralelo.</p></div>:rules.isLoading?<p>Cargando…</p>:rules.isError?<p className="error">No se pudieron cargar los horarios.</p>:Object.keys(groups).length?<div className="quarter-groups">{Object.keys(groups).sort().map(key=>{const [gy,gq]=key.split('-T');const entries=groups[key].sort((a:any,b:any)=>a.weekday-b.weekday||a.startsAtMinute-b.startsAtMinute);const weekly=entries.reduce((n:number,r:any)=>n+r.endsAtMinute-r.startsAtMinute,0);const days=weekdays.map((day,i)=>({day,i,rules:entries.filter((r:any)=>r.weekday===i)})).filter(d=>d.rules.length);return <article className="quarter-card" key={key}><header><div><span className="quarter-tag">T{gq} · {gy}</span><h3>{quarterNames[Number(gq)]}</h3><p>Vigente {String(entries[0].validFrom).slice(0,10)} – {String(entries[0].validTo).slice(0,10)}</p></div><div className="quarter-summary"><b>{Math.floor(weekly/60)} h {weekly%60?weekly%60+' min':''}</b><span>por semana</span></div></header><div className="shift-table"><div className="shift-table-head"><span>Día</span><span>Mañana</span><span>Tarde</span></div>{days.map(d=><div className="shift-table-row" key={d.i}><b className="shift-day-name">{d.day}</b>{(['morning','afternoon'] as const).map((kind,index)=>{const rule=d.rules.find((r:any)=>index===0?r.startsAtMinute<840:r.startsAtMinute>=840);return <div className="shift-cell" key={kind}>{rule?<><span className={'shift-kind '+kind}>{index===0?'Mañana':'Tarde'}</span><b className="shift-cell-time">{time(rule.startsAtMinute)}–{time(rule.endsAtMinute)}</b><ShiftReservation session={session} professionalId={professionalId} weekday={d.i} startsAtMinute={rule.startsAtMinute} validFrom={String(entries[0].validFrom).slice(0,10)} validTo={String(entries[0].validTo).slice(0,10)}/><button type="button" className="add-reservation edit-shift" onClick={()=>beginRuleEdit(rule)}><span>✎</span>Editar turno</button></>:<span className="no-shift">Sin turno</span>}</div>})}</div>)}</div></article>})}</div>:<p className="empty">Aún no tiene turnos. Añade mañana o tarde para cada día.</p>}
    </section></section></>;
}

type CalendarDay = { date: string; totalMinutes: number; occupiedMinutes: number; status: 'closed' | 'free' | 'partial' | 'full' };
function AvailabilityCalendar({ session }: { session: Session }) {
  const [visibleMonth, setVisibleMonth] = useState(() => { const now = new Date(); return new Date(now.getFullYear(), Math.floor(now.getMonth() / 3) * 3, 1); });
  const [selectedDate, setSelectedDate] = useState('');
  const year = visibleMonth.getFullYear();
  const calendar = useQuery({ queryKey: ['calendar', year], queryFn: () => request('/dashboard/calendar?year=' + year, session.accessToken) });
  const dayAgenda = useQuery({ queryKey: ['calendar-day', selectedDate], queryFn: () => request('/dashboard/day?date=' + selectedDate, session.accessToken), enabled: Boolean(selectedDate) });
  const byDate = new Map<string, CalendarDay>((calendar.data?.days ?? []).map((day: CalendarDay) => [day.date, day]));
  const locale = 'es-ES';
  const labelFor = (day: CalendarDay) => ({ closed: 'Horario no configurado', free: 'Libre', partial: 'Con horas disponibles', full: 'Ocupado toda la jornada' })[day.status];
  function monthView(month: number) {
    const first = new Date(year, month, 1); const count = new Date(year, month + 1, 0).getDate(); const offset = (first.getDay() + 6) % 7;
    return <section className="calendar-month" key={month}><h3>{first.toLocaleDateString(locale, { month: 'long' })}</h3><div className="calendar-grid">{['L','M','X','J','V','S','D'].map((day, i) => <span className="calendar-weekday" key={i}>{day}</span>)}{Array.from({ length: offset }, (_, i) => <span className="calendar-blank" key={'blank' + i} />)}{Array.from({ length: count }, (_, i) => { const date = year + '-' + String(month + 1).padStart(2, '0') + '-' + String(i + 1).padStart(2, '0'); const day = byDate.get(date) ?? { date, totalMinutes: 0, occupiedMinutes: 0, status: 'closed' as const }; const available = Math.max(0, day.totalMinutes - day.occupiedMinutes); const hours = Math.floor(available / 60); return <button type="button" key={date} onClick={() => setSelectedDate(date)} className={'calendar-day day-' + day.status + (selectedDate === date ? ' selected' : '')} title={labelFor(day) + (day.totalMinutes ? ` · ${hours} h libres` : '')} aria-label={date + ': ' + labelFor(day) + '. Abrir agenda'} aria-pressed={selectedDate === date}>{i + 1}</button>; })}</div></section>;
  }
  const selectedLabel = selectedDate ? new Date(`${selectedDate}T12:00:00`).toLocaleDateString(locale, { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }) : '';
  return <section className="calendar-panel"><div className="calendar-heading"><div><p className="eyebrow">Disponibilidad anual</p><h2>Agenda · {year}</h2><p>Vista trimestral: consulta tres meses a la vez. Pulsa un día para abrir su agenda.</p></div><div className="calendar-controls"><button className="secondary" aria-label="Trimestre anterior" onClick={() => setVisibleMonth(new Date(year, visibleMonth.getMonth() - 3, 1))}>‹</button><span>{Math.floor(visibleMonth.getMonth() / 3) + 1} / 4</span><button className="secondary" aria-label="Trimestre siguiente" onClick={() => setVisibleMonth(new Date(year, visibleMonth.getMonth() + 3, 1))}>›</button></div></div>{calendar.isLoading ? <p>Cargando disponibilidad…</p> : calendar.isError ? <p className="error">No se pudo cargar la disponibilidad.</p> : <><div className="calendar-months">{[0,1,2].map(offset => monthView(visibleMonth.getMonth() + offset))}</div><div className="calendar-legend"><span><i className="day-free" />Libre, sin citas</span><span><i className="day-partial" />Hay citas y horas libres</span><span><i className="day-full" />Ocupado toda la jornada</span><span><i className="day-closed" />Sin horario configurado</span></div></>}{selectedDate && <section className="day-agenda"><div className="day-agenda-heading"><div><p className="eyebrow">Agenda del día · {dayAgenda.data?.timezone ?? ''}</p><h3>{selectedLabel}</h3><p>{dayAgenda.data ? `${dayAgenda.data.appointmentCount} citas · ${dayAgenda.data.professionals.length} profesionales activos` : 'Cargando citas y disponibilidad…'}</p></div><button className="secondary" onClick={() => setSelectedDate('')}>Cerrar</button></div>{dayAgenda.isLoading ? <p>Cargando agenda del día…</p> : dayAgenda.isError ? <p className="error">No se pudo cargar la agenda. Vuelve a intentarlo.</p> : dayAgenda.data.professionals.length === 0 ? <p className="empty">No hay profesionales activos para esta fecha.</p> : <div className="day-professionals">{dayAgenda.data.professionals.map((professional: any) => <article className="professional-day" key={professional.id}><header><div><h4>{professional.name}</h4><p>{professional.specialty || 'Especialidad no indicada'}</p></div><span className="day-count">{professional.appointments.length} {professional.appointments.length === 1 ? 'cita' : 'citas'}</span></header><div className="day-meta"><b>Turno</b><span>{professional.schedule.length ? professional.schedule.map((x: any) => `${x.start}–${x.end}`).join(' · ') : 'Sin horario configurado'}</span></div>{professional.services.length > 0 && <div className="day-meta"><b>Servicios ofrecidos</b><span>{professional.services.map((x: any) => `${x.name} (${x.durationMinutes} min)`).join(' · ')}</span></div>}{professional.appointments.length > 0 ? <div className="day-appointments">{professional.appointments.map((appointment: any) => <div className="day-appointment" key={appointment.id}><div className="appointment-time">{appointment.start}–{appointment.end}</div><div className="appointment-detail"><b>{appointment.patient.firstName} {appointment.patient.lastName}</b><span>{appointment.patient.phone || 'Sin teléfono'}{appointment.patient.email ? ` · ${appointment.patient.email}` : ''}</span></div><div className="appointment-detail"><span>{appointment.service ? `${appointment.service.name} · ${appointment.service.durationMinutes} min` : 'Tratamiento sin asignar'} · Sala: {appointment.room?.name ?? 'Sin asignar'}</span><span className={'appointment-status status-' + appointment.status.toLowerCase()}>{({ SCHEDULED: 'Programada', CONFIRMED: 'Confirmada', COMPLETED: 'Completada', NO_SHOW: 'No asistió' } as Record<string,string>)[appointment.status] ?? appointment.status}</span></div></div>)}</div> : <p className="empty day-empty">No hay citas reservadas en su jornada.</p>}{professional.timeOff.length > 0 && <div className="day-meta"><b>Ausencias</b><span>{professional.timeOff.map((x: any) => `${x.start}–${x.end}${x.reason ? ` · ${x.reason}` : ''}`).join(' · ')}</span></div>}<div className="day-meta"><b>Huecos disponibles</b><span>{professional.freeSlots.length ? professional.freeSlots.map((x: any) => `${x.start}–${x.end}`).join(' · ') : 'Sin huecos disponibles'}</span></div></article>)}</div>}{dayAgenda.data?.appointmentCount > 0 && <p className="agenda-note">Cada cita incluye su tratamiento y duración predeterminada, junto con el paciente, profesional, sala y estado.</p>}</section>}</section>;
}
function Dashboard({ session, logout }: { session: Session; logout: () => void }) {
  const [view, setView] = useState<View>('Resumen'); const summary = useQuery({ queryKey: ['summary'], queryFn: () => request('/dashboard/summary', session.accessToken) }); const clinic = useQuery({ queryKey: ['clinic'], queryFn: () => request('/clinic/me', session.accessToken) });
  if (summary.isLoading || clinic.isLoading) return <main className="center">Cargando tu clínica…</main>;
  if (summary.isError || clinic.isError || !summary.data || !clinic.data) return <main className="center"><section className="load-error"><div className="brand">Nexo<span>Flow</span></div><h1>No se pudo cargar la clínica</h1><p>La API no respondió correctamente. Comprueba tu conexión e inténtalo de nuevo.</p><button className="primary" onClick={() => { void summary.refetch(); void clinic.refetch(); }}>Reintentar</button><button className="link" onClick={logout}>Volver a iniciar sesión</button></section></main>;
  const terms: Terminology = { ...clinicTerminology, ...(clinic.data.terminology ?? {}) }; const nav: View[] = ['Resumen','Agenda','Pacientes','Profesionales','Servicios','Tratamientos','Seguimiento','Horarios']; const navLabel: Record<View, string> = { Resumen: 'Resumen', Agenda: terms.appointments[0].toUpperCase() + terms.appointments.slice(1), Pacientes: terms.customers[0].toUpperCase() + terms.customers.slice(1), Profesionales: terms.professionals[0].toUpperCase() + terms.professionals.slice(1), Servicios: terms.services[0].toUpperCase() + terms.services.slice(1), Tratamientos: 'Tratamientos', Seguimiento: 'Seguimiento', Horarios: 'Horarios' };
  return <div className="shell"><aside><div className="brand">Nexo<span>Flow</span></div><nav>{nav.map(x => <button className={view === x ? 'active' : ''} onClick={() => setView(x)} key={x}>{navLabel[x]}</button>)}</nav><button className="logout" onClick={logout}>Cerrar sesión</button></aside><main>{view === 'Resumen' ? <><header><div><p className="eyebrow">{clinic.data.specialty}</p><h1>Buenos días, {session.user.name}</h1><p>{clinic.data.name} · {clinic.data.timezone}</p></div></header><section className="metrics"><article><span>{navLabel.Pacientes}</span><strong>{summary.data.patients}</strong></article><article><span>{terms.appointments[0].toUpperCase() + terms.appointments.slice(1)} de hoy</span><strong>{summary.data.appointmentsToday}</strong></article><article><span>Próxima {terms.appointment}</span><strong>{summary.data.upcoming[0] ? new Date(summary.data.upcoming[0].startsAt).toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' }) : '—'}</strong></article></section><AvailabilityCalendar session={session} /></> : view === 'Agenda' ? <Agenda session={session} /> : view === 'Tratamientos' ? <TreatmentDurations session={session} /> : view === 'Seguimiento' ? <FollowUps session={session} /> : view === 'Horarios' ? <Schedules session={session} /> : <Directory session={session} view={view} />}</main></div>;
}
function Access({ onSession }: { onSession: (session: Session) => void }) { const [register,setRegister]=useState(true); const [message,setMessage]=useState(''); async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{const r=await fetch(`${api}${register?'/auth/register':'/auth/login'}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(register?d:{email:d.email,password:d.password})});const x=await r.json();if(!r.ok)throw Error(Array.isArray(x.message)?x.message.join(', '):x.message);onSession(x)}catch(e){setMessage(e instanceof Error?e.message:'Error')}} return <main className="access"><section><div className="brand">Nexo<span>Flow</span></div><h1>{register?'Crea tu negocio':'Bienvenido de nuevo'}</h1><form onSubmit={submit}>{register&&<><label>Nombre del negocio<input name="clinicName" required minLength={2}/></label><label>Sector<select name="businessType" defaultValue="CLINIC"><option value="CLINIC">Clínica o salud</option><option value="BEAUTY">Belleza y bienestar</option><option value="FITNESS">Fitness y deporte</option><option value="EDUCATION">Educación</option><option value="PROFESSIONAL_SERVICES">Servicios profesionales</option><option value="HOME_SERVICES">Servicios a domicilio</option><option value="AUTOMOTIVE">Taller y automoción</option><option value="OTHER">Otro negocio de servicios</option></select></label><label>Especialidad o actividad<input name="specialty" required/></label><label>Tu nombre<input name="name" required minLength={2}/></label></>}<label>Correo electrónico<input name="email" type="email" required/></label><label>Contraseña<input name="password" type="password" minLength={register?12:1} required/></label>{message&&<p className="error">{message}</p>}<button className="primary">{register?'Crear negocio':'Iniciar sesión'}</button></form><button className="link" onClick={()=>setRegister(!register)}>{register?'Ya tengo una cuenta':'Crear un negocio nuevo'}</button></section></main>; }
function App(){const [s,setS]=useState<Session|null>(()=>{const x=localStorage.getItem('nexoclinic-session');return x?JSON.parse(x):null});const set=(x:Session)=>{localStorage.setItem('nexoclinic-session',JSON.stringify(x));setS(x)};useEffect(()=>{const expire=()=>{localStorage.removeItem('nexoclinic-session');setS(null)};window.addEventListener('nexoclinic:session-expired',expire);return()=>window.removeEventListener('nexoclinic:session-expired',expire)},[]);return s?<Dashboard session={s} logout={()=>{localStorage.removeItem('nexoclinic-session');setS(null)}}/>:<Access onSession={set}/>};
createRoot(document.getElementById('root')!).render(<React.StrictMode><QueryClientProvider client={new QueryClient()}><App/></QueryClientProvider></React.StrictMode>);
